// FE-07: the UI's layout code against layouts the server decoded.
//
// The UI rebuilds every sheet from the tree string the server sends (getTree
// and joinRects, src/utils/rect.ts) and places the parts (computeLayout,
// src/utils/layout.ts). That code duplicates the server's reduce()
// (problem/csp2d/problem.go) and must not diverge from it. The vectors
// (test/testdata/forests/forests.json) are generated by the server
// (test/unit/csp2d/forest_vectors_test.go, UT-FV-01): random instances as the
// UI enters them (decimal and fraction sizes, saw widths, sheets entered either
// way round) and random genotypes decoded into sheets, with the size the server
// computed for each sheet.

import {test} from 'node:test';
import * as assert from 'node:assert/strict';
import {getTree} from '../src/utils/rect';
import {computeLayout} from '../src/utils/layout';
import {parseSize} from '../src/utils/numbers';
import {checkPlacement, contentOf, EPS, leafCount, loadRepoJson, makeModel, num, setLayout} from './helpers';

interface ForestSheet {
    tree: string;
    long: number;
    short: number;
}

interface ForestCase {
    name: string;
    unit: 'mm' | 'in';
    parts: string[][];
    sheet: string[] | null;
    sawWidth: string;
    layouts: { postfix: string, sheets: ForestSheet[] }[];
}

const cases = loadRepoJson<ForestCase[]>('test/testdata/forests/forests.json');

test('the forest vectors are there and span several sheets', () => {
    assert.ok(cases.length >= 100, `${cases.length} cases`);
    assert.ok(cases.some(c => c.layouts.some(l => l.sheets.length > 1)), 'no multi-sheet layout');
    assert.ok(cases.some(c => c.unit === 'in'), 'no fraction case');
    assert.ok(cases.some(c => c.sheet && num(parseSize(c.sheet[0], true)) < num(parseSize(c.sheet[1], true))), 'no sheet entered as width < length');
});

for (const c of cases) {
    test(`server forests: ${c.name}`, () => {
        const model = makeModel(c.unit, c.parts, c.sheet, c.sawWidth);
        const gap = parseSize(model.sawWidth, model.fraction); // as Visualizer does
        const sizeOf = (label: string): [number, number] => {
            const part = model.parts.find(p => p.label === label)!;
            return [num(parseSize(part.width, model.fraction)), num(parseSize(part.length, model.fraction))];
        };
        const sheet = model.getNumericSheets(true);
        const sheetLong = sheet ? Math.max(sheet.width as number, sheet.length as number) : 0;
        const sheetShort = sheet ? Math.min(sheet.width as number, sheet.length as number) : 0;

        for (const layout of c.layouts) {
            setLayout(model, layout.sheets.map(s => s.tree));
            layout.sheets.forEach((expected, index) => {
                const where = `${c.name}, genotype ${layout.postfix}, sheet ${index} (${expected.tree})`;
                const root = getTree(model, 0, index, gap);

                // 1. joinRects reproduces reduce(): the packed parts have the
                // size the server computed for the sheet.
                const content = contentOf(root);
                assert.ok(Math.abs(content.getWidth() - expected.long) < EPS && Math.abs(content.getHeight() - expected.short) < EPS,
                    `${where}: UI size ${content.getWidth()} x ${content.getHeight()}, server ${expected.long} x ${expected.short}`);

                // 2. With a sheet, the drawn rect is the sheet: the waste fills it.
                if (sheet) {
                    assert.ok(Math.abs(root.getWidth() - sheetLong) < EPS && Math.abs(root.getHeight() - sheetShort) < EPS,
                        `${where}: drawn ${root.getWidth()} x ${root.getHeight()}, sheet ${sheetLong} x ${sheetShort} (entered ${c.sheet!.join(' x ')})`);
                }

                // 3. computeLayout places every part at its size, inside the
                // sheet, without overlaps.
                const problems = checkPlacement(root, computeLayout(root, 1, 0, 0), sizeOf, leafCount(expected.tree));
                assert.deepEqual(problems, [], `${where}:\n  ${problems.join('\n  ')}`);
            });
        }
    });
}
